-- LOT 15 — Learning Experience Engine / Study Workspace
CREATE TABLE IF NOT EXISTS learning_study_sessions (id varchar(64) PRIMARY KEY, account_id varchar(64) NOT NULL, course_id varchar(64) NOT NULL, chapter_id varchar(64), mode varchar(24) NOT NULL, state varchar(24) NOT NULL, started_at timestamptz NOT NULL, updated_at timestamptz NOT NULL, ended_at timestamptz, active_seconds integer NOT NULL DEFAULT 0 CHECK(active_seconds>=0), last_position varchar(255), objective varchar(500), row_version integer NOT NULL DEFAULT 1 CHECK(row_version>=1));
CREATE INDEX IF NOT EXISTS ix_learning_sessions_account_state ON learning_study_sessions(account_id,state,updated_at DESC);
CREATE INDEX IF NOT EXISTS ix_learning_sessions_course ON learning_study_sessions(account_id,course_id,updated_at DESC);
CREATE UNIQUE INDEX IF NOT EXISTS ux_learning_one_open_session ON learning_study_sessions(account_id) WHERE state IN ('active','paused');
CREATE TABLE IF NOT EXISTS learning_progress (account_id varchar(64) NOT NULL, course_id varchar(64) NOT NULL, chapter_id varchar(64) NOT NULL DEFAULT '__course__', stage varchar(24) NOT NULL, completion_ratio double precision NOT NULL DEFAULT 0 CHECK(completion_ratio BETWEEN 0 AND 1), practice_attempts integer NOT NULL DEFAULT 0, assessment_attempts integer NOT NULL DEFAULT 0, correct_answers integer NOT NULL DEFAULT 0, total_answers integer NOT NULL DEFAULT 0, updated_at timestamptz NOT NULL, PRIMARY KEY(account_id,course_id,chapter_id), CHECK(correct_answers>=0 AND total_answers>=correct_answers));
CREATE INDEX IF NOT EXISTS ix_learning_progress_account_stage ON learning_progress(account_id,stage,updated_at DESC);
CREATE TABLE IF NOT EXISTS learning_error_bank (id varchar(64) PRIMARY KEY, account_id varchar(64) NOT NULL, course_id varchar(64) NOT NULL, chapter_id varchar(64), source_type varchar(32) NOT NULL, source_id varchar(64) NOT NULL, prompt text NOT NULL, correct_answer text, attempts integer NOT NULL DEFAULT 1, resolved boolean NOT NULL DEFAULT false, next_review_at timestamptz, created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL);
CREATE INDEX IF NOT EXISTS ix_learning_error_due ON learning_error_bank(account_id,resolved,next_review_at);
CREATE TABLE IF NOT EXISTS learning_review_cards (account_id varchar(64) NOT NULL, card_id varchar(64) NOT NULL, course_id varchar(64) NOT NULL, chapter_id varchar(64), repetitions integer NOT NULL DEFAULT 0, interval_days integer NOT NULL DEFAULT 0, ease_factor double precision NOT NULL DEFAULT 2.5 CHECK(ease_factor>=1.3), due_at timestamptz NOT NULL, updated_at timestamptz NOT NULL, PRIMARY KEY(account_id,card_id));
CREATE INDEX IF NOT EXISTS ix_learning_review_due ON learning_review_cards(account_id,due_at);
